#[test]
fn max_message_bytes_limits_body_in_utf8_bytes() {
    let mut h = Harness::new();
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q", "Attributes": {"MaxMessageBytes": 4}}));
    let send = |body: &str| json!({"Command": "SendMessage", "QueueName": "q", "Body": body});
    h.ok(send("abcd"));
    h.ok(send("\u{e9}\u{e9}"));
    assert_eq!(h.err(send("abcde")), "InvalidParameterValue");
    assert_eq!(h.err(send("\u{e9}\u{e9}a")), "InvalidParameterValue");
}

#[test]
fn max_message_bytes_check_comes_before_unsupported_operation() {
    let mut h = Harness::new();
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q", "Attributes": {"MaxMessageBytes": 1}}));
    let code = h.err(json!({"Command": "SendMessage", "QueueName": "q", "Body": "ab", "GroupId": "g"}));
    assert_eq!(code, "InvalidParameterValue");
}

#[test]
fn set_max_message_bytes_keeps_existing_messages_and_is_validated() {
    let mut h = Harness::new();
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q"}));
    h.ok(json!({"Command": "SendMessage", "QueueName": "q", "Body": "long body"}));
    h.ok(json!({"Command": "SetQueueAttributes", "QueueName": "q", "Attributes": {"MaxMessageBytes": 1}}));
    let r = h.ok(json!({"Command": "ReceiveMessage", "QueueName": "q"}));
    assert_eq!(r["Messages"][0]["Body"], "long body");
