fn max_message_bytes_takes_part_in_create_queue_idempotence() {
    let mut h = Harness::new();
    let create = |n: u64| json!({"Command": "CreateQueue", "QueueName": "q", "Attributes": {"MaxMessageBytes": n}});
    h.ok(create(10));
    h.ok(create(10));
    assert_eq!(h.err(create(11)), "QueueAlreadyExists");
}
