mod common;

use common::Harness;
use serde_json::{Value, json};

fn setup() -> Harness {
    let mut h = Harness::new();
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q"}));
    h
}

fn tag(h: &mut Harness, tags: Value) -> Value {
    h.run(json!({"Command": "TagQueue", "QueueName": "q", "Tags": tags}))
}

fn tags(h: &mut Harness) -> Value {
    h.ok(json!({"Command": "ListQueueTags", "QueueName": "q"}))["Tags"].clone()
}

#[test]
fn new_queue_has_no_tags() {
    let mut h = setup();
    assert_eq!(tags(&mut h), json!({}));
}

#[test]
fn tag_sets_and_replaces_values() {
    let mut h = setup();
    assert_eq!(tag(&mut h, json!({"a": "1", "b": ""})), json!({"ok": true}));
    assert_eq!(tag(&mut h, json!({"a": "2", "c": "3"})), json!({"ok": true}));
    assert_eq!(tags(&mut h), json!({"a": "2", "b": "", "c": "3"}));
    assert_eq!(tag(&mut h, json!({})), json!({"ok": true}));
    assert_eq!(tags(&mut h), json!({"a": "2", "b": "", "c": "3"}));
}

#[test]
fn keys_are_case_sensitive() {
    let mut h = setup();
    tag(&mut h, json!({"a": "1", "A": "2"}));
    assert_eq!(tags(&mut h), json!({"a": "1", "A": "2"}));
}

#[test]
fn invalid_tag_input_changes_nothing() {
    let mut h = setup();
    tag(&mut h, json!({"keep": "x"}));
    let long_key = "k".repeat(129);
    let long_value = "v".repeat(257);
    let bad: Vec<Value> = vec![
        json!({"": "x"}),
        json!({"bad key": "x"}),
        json!({long_key: "x"}),
        json!({"ok": 1}),
        json!({"ok": null}),
        json!({"ok": long_value}),
        json!({"good": "x", "bad!": "x"}),
    ];
    for t in bad {
        let r = tag(&mut h, t.clone());
        assert_eq!(r["error"]["code"], "InvalidParameterValue", "{t}");
    }
    assert_eq!(tags(&mut h), json!({"keep": "x"}));
}

#[test]
fn value_limit_counts_utf8_bytes() {
    let mut h = setup();
    assert_eq!(tag(&mut h, json!({"a": "v".repeat(256)})), json!({"ok": true}));
    // 129 two-byte characters are 258 bytes.
    let r = tag(&mut h, json!({"b": "\u{e9}".repeat(129)}));
    assert_eq!(r["error"]["code"], "InvalidParameterValue");
    assert_eq!(tag(&mut h, json!({"b": "\u{e9}".repeat(128)})), json!({"ok": true}));
}

#[test]
fn tags_must_be_an_object_and_required() {
    let mut h = setup();
    assert_eq!(
        h.err(json!({"Command": "TagQueue", "QueueName": "q"})),
        "MissingParameter"
    );
    assert_eq!(
        h.err(json!({"Command": "TagQueue", "QueueName": "q", "Tags": []})),
        "InvalidParameterValue"
    );
}

#[test]
fn at_most_fifty_tags() {
    let mut h = setup();
    let fifty: serde_json::Map<String, Value> =
        (0..50).map(|i| (format!("k{i}"), json!("v"))).collect();
    assert_eq!(tag(&mut h, Value::Object(fifty)), json!({"ok": true}));
    // Replacing an existing key stays within the limit.
    assert_eq!(tag(&mut h, json!({"k0": "new"})), json!({"ok": true}));
    let r = tag(&mut h, json!({"extra": "v"}));
    assert_eq!(r["error"]["code"], "LimitExceeded");
    assert_eq!(tags(&mut h).as_object().unwrap().len(), 50);
    assert_eq!(tags(&mut h)["k0"], "new");
    // A failed batch of tags sets none of them, and removing one makes room.
    h.ok(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": ["k1"]}));
    let r = tag(&mut h, json!({"x": "1", "y": "2", "k0": "again"}));
    assert_eq!(r["error"]["code"], "LimitExceeded");
    assert_eq!(tags(&mut h)["k0"], "new");
    assert_eq!(tag(&mut h, json!({"x": "1"})), json!({"ok": true}));
}

#[test]
fn untag_removes_given_keys_and_ignores_missing_ones() {
    let mut h = setup();
    tag(&mut h, json!({"a": "1", "b": "2"}));
    let r = h.ok(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": ["a", "zzz", "a"]}));
    assert_eq!(r, json!({"ok": true}));
    assert_eq!(tags(&mut h), json!({"b": "2"}));
    h.ok(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": []}));
    assert_eq!(tags(&mut h), json!({"b": "2"}));
}

#[test]
fn untag_validates_keys_before_removing_any() {
    let mut h = setup();
    tag(&mut h, json!({"a": "1"}));
    for keys in [json!(["a", 5]), json!(["a", "bad key"]), json!(["a", ""]), json!("a")] {
        let code = h.err(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": keys}));
        assert_eq!(code, "InvalidParameterValue", "{keys}");
    }
    assert_eq!(h.err(json!({"Command": "UntagQueue", "QueueName": "q"})), "MissingParameter");
    assert_eq!(tags(&mut h), json!({"a": "1"}));
}

#[test]
fn tag_commands_check_the_queue_after_parameters() {
    let mut h = Harness::new();
    for command in ["TagQueue", "UntagQueue", "ListQueueTags"] {
        let code = h.err(json!({"Command": command, "QueueName": "nope", "Tags": {}, "TagKeys": []}));
        assert_eq!(code, "QueueDoesNotExist", "{command}");
        let code = h.err(json!({"Command": command}));
        assert_eq!(code, "MissingParameter", "{command}");
    }
}

#[test]
fn tags_are_not_attributes_and_survive_purge_but_not_delete() {
    let mut h = setup();
    tag(&mut h, json!({"a": "1"}));
    let attrs = h.ok(json!({"Command": "GetQueueAttributes", "QueueName": "q"}));
    assert!(attrs["Attributes"].get("Tags").is_none());
    // Tags do not take part in CreateQueue rule 4.
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q"}));
    h.ok(json!({"Command": "PurgeQueue", "QueueName": "q"}));
    assert_eq!(tags(&mut h), json!({"a": "1"}));
    h.ok(json!({"Command": "DeleteQueue", "QueueName": "q"}));
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q"}));
    assert_eq!(tags(&mut h), json!({}));
}
