//! Batch commands (SPEC-feature section 2).

use std::collections::HashSet;

use serde_json::{Value, json};

use super::{Broker, Members, members};
use crate::error::{Error, ErrorCode, Result};
use crate::request::Params;

const MAX_ENTRIES: usize = 10;
const MAX_ENTRY_ID_CHARS: usize = 80;

fn invalid_entry_id(message: &str) -> Error {
    Error::new(ErrorCode::InvalidBatchEntryId, message)
}

/// The `Id` of an entry, which must be an object (rule 3).
fn entry_id<'a>(entry: &'a Value) -> Result<(&'a str, Params<'a>)> {
    let object = entry
        .as_object()
        .ok_or_else(|| invalid_entry_id("a batch entry must be an object"))?;
    let params = Params::new(object);
    let id = params
        .identifier("Id", MAX_ENTRY_ID_CHARS)
        .ok()
        .flatten()
        .ok_or_else(|| {
            invalid_entry_id("`Id` must be 1 to 80 characters from A-Z a-z 0-9 _ -")
        })?;
    Ok((id, params))
}

/// Applies rules 1 to 4 and returns the entries with their ids.
fn parse_entries(entries: &[Value]) -> Result<Vec<(&str, Params<'_>)>> {
    if entries.is_empty() {
        return Err(Error::new(
            ErrorCode::EmptyBatchRequest,
            "`Entries` has no entry",
        ));
    }
    if entries.len() > MAX_ENTRIES {
        return Err(Error::new(
            ErrorCode::TooManyEntriesInBatchRequest,
            format!("`Entries` has more than {MAX_ENTRIES} entries"),
        ));
    }
    let parsed = entries.iter().map(entry_id).collect::<Result<Vec<_>>>()?;
    let mut seen = HashSet::with_capacity(parsed.len());
    if let Some((id, _)) = parsed.iter().find(|(id, _)| !seen.insert(*id)) {
        return Err(Error::new(
            ErrorCode::BatchEntryIdsNotDistinct,
            format!("entry id `{id}` is used twice"),
        ));
    }
    Ok(parsed)
}

impl Broker {
    pub(super) fn send_message_batch(&mut self, params: Params<'_>) -> Result<Members> {
        self.batch(params, |broker, name, entry| {
            entry.require(&["Body"])?;
            broker.send_to(name, entry)
        })
    }

    pub(super) fn delete_message_batch(&mut self, params: Params<'_>) -> Result<Members> {
        self.batch(params, |broker, name, entry| {
            entry.require(&["ReceiptHandle"])?;
            broker.delete_in(name, entry)
        })
    }

    /// Runs `handle` for each entry in order. An entry that fails is
    /// reported in `Failed` and does not stop the others.
    fn batch(
        &mut self,
        params: Params<'_>,
        handle: fn(&mut Broker, &str, Params<'_>) -> Result<Members>,
    ) -> Result<Members> {
        params.require(&["QueueName", "Entries"])?;
        let name = params.string("QueueName")?.expect("required");
        let entries = params.array("Entries")?.expect("required");
        self.queue_mut(name)?;
        let entries = parse_entries(entries)?;

        let mut successful = Vec::new();
        let mut failed = Vec::new();
        for (id, entry) in entries {
            match handle(self, name, entry) {
                Ok(mut result) => {
                    result.insert("Id".into(), json!(id));
                    successful.push(Value::Object(result));
                }
                Err(error) => failed.push(json!({ "Id": id, "error": error.to_json() })),
            }
        }
        Ok(members([
            ("Successful", Value::Array(successful)),
            ("Failed", Value::Array(failed)),
        ]))
    }
}
