mod common;

use common::Harness;
use serde_json::{Value, json};

fn create(h: &mut Harness, name: &str, attributes: Value) {
    h.ok(json!({"Command": "CreateQueue", "QueueName": name, "Attributes": attributes}));
}

fn send_batch(h: &mut Harness, queue: &str, entries: Value) -> Value {
    h.ok(json!({"Command": "SendMessageBatch", "QueueName": queue, "Entries": entries}))
}

fn delete_batch(h: &mut Harness, queue: &str, entries: Value) -> Value {
    h.ok(json!({"Command": "DeleteMessageBatch", "QueueName": queue, "Entries": entries}))
}

fn entry_error(response: &Value, index: usize) -> (&str, &str) {
    let failed = &response["Failed"][index];
    (
        failed["Id"].as_str().unwrap(),
        failed["error"]["code"].as_str().unwrap(),
    )
}

#[test]
fn send_batch_assigns_ids_in_order() {
    let mut h = Harness::new();
    create(&mut h, "q", json!({}));
    let r = send_batch(&mut h, "q", json!([{"Id": "a", "Body": "x"}, {"Id": "b", "Body": "y"}]));
    assert_eq!(
        r,
        json!({"ok": true, "Failed": [],
               "Successful": [{"Id": "a", "MessageId": "m-1"}, {"Id": "b", "MessageId": "m-2"}]})
    );
    let r = h.ok(json!({"Command": "ReceiveMessage", "QueueName": "q", "MaxMessages": 2}));
    assert_eq!(r["Messages"][0]["Body"], "x");
    assert_eq!(r["Messages"][1]["Body"], "y");
}

#[test]
fn send_batch_reports_failures_and_continues() {
    let mut h = Harness::new();
    create(&mut h, "q", json!({"MaxMessageBytes": 3}));
    let r = send_batch(
        &mut h,
        "q",
        json!([
            {"Id": "1", "Body": "ok"},
            {"Id": "2", "Body": "too long"},
            {"Id": "3"},
            {"Id": "4", "Body": 5},
            {"Id": "5", "Body": "abc", "GroupId": "g"},
            {"Id": "6", "Body": "fine", "DelaySeconds": null},
            {"Id": "7", "Body": "yes", "Other": 1},
        ]),
    );
    assert_eq!(r["Successful"], json!([
        {"Id": "1", "MessageId": "m-1"}, {"Id": "7", "MessageId": "m-2"}]));
    let failures: Vec<(&str, &str)> = (0..5).map(|i| entry_error(&r, i)).collect();
    assert_eq!(failures, vec![
        ("2", "InvalidParameterValue"),
        ("3", "MissingParameter"),
        ("4", "InvalidParameterValue"),
        ("5", "UnsupportedOperation"),
        ("6", "InvalidParameterValue"),
    ]);
    assert!(r["Failed"][0]["error"]["message"].is_string());
}

#[test]
fn fifo_batch_sees_earlier_entries_and_deduplicates() {
    let mut h = Harness::new();
    create(&mut h, "q.fifo", json!({"Fifo": true}));
    let r = send_batch(
        &mut h,
        "q.fifo",
        json!([
            {"Id": "a", "Body": "x", "GroupId": "g", "DeduplicationId": "d"},
            {"Id": "b", "Body": "y", "GroupId": "g", "DeduplicationId": "d"},
            {"Id": "c", "Body": "z", "GroupId": "g", "DeduplicationId": "e"},
            {"Id": "d", "Body": "w", "DeduplicationId": "f"},
        ]),
    );
    assert_eq!(r["Successful"], json!([
        {"Id": "a", "MessageId": "m-1", "SequenceNumber": 1},
        {"Id": "b", "MessageId": "m-1", "SequenceNumber": 1},
        {"Id": "c", "MessageId": "m-2", "SequenceNumber": 2},
    ]));
    assert_eq!(entry_error(&r, 0), ("d", "MissingParameter"));
}

#[test]
fn send_batch_respects_message_limit_within_one_batch() {
    let mut h = Harness::new();
    create(&mut h, "q", json!({}));
    for _ in 0..9999 {
        let entries: Vec<Value> = (0..10).map(|i| json!({"Id": format!("e{i}"), "Body": "x"})).collect();
        let r = send_batch(&mut h, "q", Value::Array(entries));
        assert_eq!(r["Failed"], json!([]));
    }
    let entries: Vec<Value> = (0..10).map(|i| json!({"Id": format!("e{i}"), "Body": "x"})).collect();
    let r = send_batch(&mut h, "q", Value::Array(entries));
    assert_eq!(r["Successful"].as_array().unwrap().len(), 10);
    let r = send_batch(&mut h, "q", json!([{"Id": "late", "Body": "x"}]));
    assert_eq!(entry_error(&r, 0), ("late", "LimitExceeded"));
}

#[test]
fn delete_batch_deletes_and_reports_bad_handles() {
    let mut h = Harness::new();
    create(&mut h, "q", json!({}));
    send_batch(&mut h, "q", json!([{"Id": "a", "Body": "x"}, {"Id": "b", "Body": "y"}]));
    h.ok(json!({"Command": "ReceiveMessage", "QueueName": "q", "MaxMessages": 2}));
    let r = delete_batch(
        &mut h,
        "q",
        json!([
            {"Id": "1", "ReceiptHandle": "r-1"},
            {"Id": "2", "ReceiptHandle": "r-1"},
            {"Id": "3", "ReceiptHandle": "r-99"},
            {"Id": "4"},
            {"Id": "5", "ReceiptHandle": 7},
            {"Id": "6", "ReceiptHandle": "r-2"},
        ]),
    );
    assert_eq!(r["Successful"], json!([{"Id": "1"}, {"Id": "6"}]));
    let failures: Vec<(&str, &str)> = (0..4).map(|i| entry_error(&r, i)).collect();
    assert_eq!(failures, vec![
        ("2", "ReceiptHandleExpired"),
        ("3", "ReceiptHandleInvalid"),
        ("4", "MissingParameter"),
        ("5", "InvalidParameterValue"),
    ]);
    let counts = h.ok(json!({"Command": "GetQueueAttributes", "QueueName": "q"}))["Counts"].clone();
    assert_eq!(counts, json!({"Visible": 0, "InFlight": 0, "Delayed": 0}));
}

#[test]
fn delete_batch_all_failed_is_still_a_success() {
    let mut h = Harness::new();
    create(&mut h, "q", json!({}));
    let r = delete_batch(&mut h, "q", json!([{"Id": "a", "ReceiptHandle": "r-1"}]));
    assert_eq!(r["Successful"], json!([]));
    assert_eq!(entry_error(&r, 0), ("a", "ReceiptHandleInvalid"));
}

#[test]
fn batch_request_rules() {
    let mut h = Harness::new();
    create(&mut h, "q", json!({}));
    let eleven: Vec<Value> = (0..11).map(|i| json!({"Id": format!("e{i}"), "Body": "x"})).collect();
    let ten_plus_bad: Vec<Value> = (0..10).map(|i| json!({"Id": format!("e{i}")})).collect();
    let id81 = "a".repeat(81);
    let cases: Vec<(Value, &str)> = vec![
        (json!([]), "EmptyBatchRequest"),
        (Value::Array(eleven), "TooManyEntriesInBatchRequest"),
        (json!([{"Id": "a", "Body": "x"}, 5]), "InvalidBatchEntryId"),
        (json!([{"Body": "x"}]), "InvalidBatchEntryId"),
        (json!([{"Id": null, "Body": "x"}]), "InvalidBatchEntryId"),
        (json!([{"Id": 1, "Body": "x"}]), "InvalidBatchEntryId"),
        (json!([{"Id": "", "Body": "x"}]), "InvalidBatchEntryId"),
        (json!([{"Id": "a b", "Body": "x"}]), "InvalidBatchEntryId"),
        (json!([{"Id": id81, "Body": "x"}]), "InvalidBatchEntryId"),
        (json!([{"Id": "a", "Body": "x"}, {"Id": "a", "Body": "y"}]), "BatchEntryIdsNotDistinct"),
        (json!([{"Id": "a"}, {"Id": "a"}, 3]), "InvalidBatchEntryId"),
        (json!([[], {"Id": "a"}]), "InvalidBatchEntryId"),
    ];
